  (3, (select id from menu_categories where source_id = 1), '0003', 'Tiramisu Latte', 'تيراميسو لاتيه', '', '', 29.00, '/menu/0003-tiramisu-latte.webp', true, false, 20),
  (4, (select id from menu_categories where source_id = 1), '0004', 'Cappucino', 'كابوتشينو', 'Classic Cappuccino A rich shot of double espresso topped with equal parts steamed milk and a thick, silky layer of milk foam, dusted with cocoa powder.', 'كابوتشينو كلاسيك شوت غني من الإسبريسو المزدوج يعلوه مزيج متوازن من الحليب المبخر ورغوة الحليب المخملية الكثيفة، مع لمسة خفيفة من بودرة الكاكاو', 27.00, '/menu/0004-cappucino.webp', true, false, 30),
  (5, (select id from menu_categories where source_id = 1), '0005', 'Chamomile Tea', 'شاي البابونج', 'Chamomile Tea (Hot / Iced) A soothing, caffeine-free infusion of premium whole chamomile flowers, offering a delicate floral aroma and subtle notes of honey.', 'شاي البابونج (حار / بارد) مزمور مهدئ وخالٍ من الكافيين من أزهار البابونج الكاملة الفاخرة، يتميز بنكهة زهرية لطيفة ولمسات خفيفة من العسل.', 25.00, '/menu/0005-chamomile-tea.webp', true, false, 40),
