  (18, (select id from menu_categories where source_id = 1), '0018', 'Latte', 'لاتيه', 'Latte Smooth, rich espresso combined with silky, steamed micro-foam milk for a perfectly balanced and velvety coffee experience.', 'لاتيه إسباديسو غني وناعم ممزوج بالحليب المبخر ذو الرغوة المخملية الحريرية، لتجربة قهوة متوازنة وفاخرة.', 28.00, '/menu/0018-latte.webp', true, false, 70),
