  (95, (select id from menu_categories where source_id = 1), '0095', 'Ceremonial Matcha Latte', 'ماتشا لاتيه الاحتفالية', 'Ceremonial Matcha Latte (Hot / Iced) Japanese ceremonial matcha whisked to perfection and combined with smooth, velvety milk for a vibrant, earthy taste with natural sweetness. Served with a shot of espresso.', 'سيريمونيال ماتشا لاتيه (حار / بارد) ماتشا يابانية سيريمونيال مخفوقة بإتقان وممزوجة بالحليب المخملي الناعم، لمذاق غني ومنعش وحلاوة طبيعية. يُقدّم مع شوت إسبريسو.', 30.00, '/menu/0095-ceremonial-matcha-latte.webp', true, false, 90),
  (107, (select id from menu_categories where source_id = 1), '0107', 'Double Espresso', 'دابل اسبريسو', 'Double Espresso A bold, concentrated double shot of specialty coffee, extracted to highlight rich flavors, natural sweetness, and a velvety crema layer.', 'دبل إسبريسو جرعة مضاعفة غنية ومكثفة من القهوة المختصة، تم استخلاصها بعناية لإبراز النكهات الغنية، الحلاوة الطبيعية، وطبقة الكريما المخملية.', 22.00, '/menu/0107-double-espresso.webp', true, false, 100),
  (108, (select id from menu_categories where source_id = 1), '0108', 'English Breakfast Tea', 'شاي احمر', 'English Breakfast Tea A classic, full-bodied black tea brew delivering a rich, robust malt flavor with a bright golden-amber hue and a refreshing finish.', 'شاي أحمر إنجليش بريكفاست الشاي الأحمر الكلاسيكي الفاخر بعبير قوي ونكهة غنية ومكثفة، يتميز بلونه الذهبي الدافئ ولمسته المنعشة.', 25.00, '/menu/0108-english-breakfast-tea.webp', true, false, 110),
