  (216, (select id from menu_categories where source_id = 1), '0216', 'Cortado', 'كورتادو', 'Cortado A precise 1:1 balance of rich espresso cut with equal parts warm, silky steamed milk, served in a classic glass.', 'كورتادو توازن دقيق بنسبة 1:1 من الإسبريسو الغني مع كمية مساوية من الحليب المبخر الدافئ والمخملي، يُقدّم في كوب زجاجي كلاسيكي.', 27.00, '/menu/0216-cortado.webp', true, false, 150),
