  (132, (select id from menu_categories where source_id = 2), '0132', 'Fresh Orange Juice', 'برتقال', 'Fresh Orange Juice 100% freshly squeezed ripe oranges, naturally sweet, vibrant, and packed with refreshing citrus taste.', 'عصير برتقال طازج عصير برتقال طازج 100٪ من حبات البرتقال الناضجة، بحلاوة طبيعية ونكهة حمضية منعشة.', 32.00, '/menu/0132-fresh-orange-juice.webp', true, false, 220),
  (135, (select id from menu_categories where source_id = 2), '0135', 'Limited Colada', 'كولادا', 'Limited Colada A signature seasonal beverage layered with sweet pineapple juice and rich, thick mango juice, topped with silky coconut cream and finished with a crispy coconut crunch.', 'ليميتد كولادا مشروب موسمي مميز بطبقات من عصير الأناناس الحلو وعصير المانجو الكثيف، تعلوه كريمة جوز الهند الحريرية ومُزيّن بقرمشة جوز الهند الطازجة.', 29.00, '/menu/0135-limited-colada.webp', true, false, 230),
