  (49, (select id from menu_categories where source_id = 3), '0049', 'Brownies Chocolate Bomb', 'شوكولاتة براونيز', 'Fresh Homemade Brownie Fresh homemade brownie topped with a bowl of creamy vanilla ice cream and warm specialty chocolate sauce to pour over and melt the top.', 'براوني طازج محضر لدينا براوني طازج ومحضر لدينا يعلوه وعاء من آيس كريم الفانيليا الكريمي مع صوص الشوكولاتة الخاص الدافئ للسكب فوقه وتذويب', 45.00, '/menu/0049-brownies-chocolate-bomb.webp', true, true, 280),
  (52, (select id from menu_categories where source_id = 3), '0052', 'The French Toast', 'فرانش توست', 'The French Toast Two pieces of golden, thick-cut artisan brioche soaked in a rich vanilla-cinnamon custard, seared to perfection. Served with salted caramel drizzle, fresh berries, and a side of vanilla ice cream.', 'الفرنش توست شريحتان سميكتان من خبز البريوش الذهبي الفاخر، مغمورتان في مزيج الكاسترد بالفانيليا والقرفة الغني ومحمصلتان بإتقان. تُقدّم مع لمسة من الكراميل المملح، الفواكه التوتية الطازجة، وجانب من أيس كريم الفانيليا.', 50.00, '/menu/0052-the-french-toast.webp', true, true, 290),
  (143, (select id from menu_categories where source_id = 3), '0143', 'ice tissu cake', 'فيكتوريا كيك', 'Iced Tissue Cake An exquisite creation crafted in the shape of roasted coffee beans, featuring ultra-thin, tissue-soft layered cake infused with chilled cream and rich cocoa.', 'آيس تيشو كيك ابتكار فني ساحر على شكل حبوب القهوة المحمصة، يتميز بطبقات كيك ناعمة ورقيقة كالأنسجة، محشوة بالكريمة الباردة والكاكاو الغني.', 39.00, '/menu/0143-ice-tissu-cake.webp', true, false, 300),
  (203, (select id from menu_categories where source_id = 3), '0203', 'CHEESE CAKE', 'تشيز كيك', '', '', 38.00, '/menu/0203-cheese-cake.webp', true, false, 310),
  (204, (select id from menu_categories where source_id = 3), '0204', 'PECAN MELT', 'ذوبان البقان', 'Pecan Melt An exquisite dessert sculpted in the shape of a pecan nut, filled with signature homemade cream, a dual-biscuit base, and rich melted caramel, topped with a crunchy pecan nut finish.', 'بيكان ميلت حلوى مبتكرة ومصممة على شكل حبة البيكان، محشوة بالكريمة الخاصة المنزلية، طبقتين من البسكويت الهش، والكراميل الذائب، تعلوها مقرمشات البيكان المحمصة.', 42.00, '/menu/0204-pecan-melt.webp', true, false, 320),
  (205, (select id from menu_categories where source_id = 3), '0205', 'Golden Hive Cake', 'كيكة خلية النحل الذهبية', 'Golden Hive Cake Delicate, golden layers of honey-infused cake separated by light, velvety cream, finished with a subtle honey-crumb topping.', 'كيكة خلية النحل الذهبية طبقات ذهبية رقيقة وهشة من الكيك المحضر بعسل النحل الطبيعي، تفصل بينها كريمة مخملية خفيفة، ومتوجة بفتات العسل الهش.', 38.00, '/menu/0205-golden-hive-cake.webp', true, false, 330),
  (206, (select id from menu_categories where source_id = 3), '0206', 'Double D', 'دابل دي', 'Double D Rich chocolate sponge layered with creamy espresso-infused filling, nestled between two distinct house-made biscuits, topped with melted rich chocolate and a crunchy chocolate crumble.', 'دبل دي كيكة إسفنجية بالشوكلاتة الغنية مع طبقات من الكريمة بنكهة الإسبريسو، بين نوعين من البسكويت المحضر لدينا، يغلوها الشوكولاتة الغنية المذابة مع كرانشي الشوكولاتة المقرمش.', 37.00, '/menu/0206-double-d.webp', true, false, 340),
