  (58, (select id from menu_categories where source_id = 4), '0058', 'Cheese Croissant', 'كرواسون جبن', '', '', 26.00, '/menu/0058-cheese-croissant.webp', false, false, 360),
  (59, (select id from menu_categories where source_id = 4), '0059', 'Chocolate Croissant', 'كرواسون الشوكولاتة', '', '', 26.00, '/menu/0059-chocolate-croissant.webp', false, false, 370),
  (76, (select id from menu_categories where source_id = 4), '0076', 'Penne Pasta', 'باستا بيني', 'Penne Pasta Al dente penne folded into an Italian special sauce—a rich combination of three distinct sauces creating a creamy white base with tender pieces of chicken breast. Topped with aged Parmesan, white cheddar, and a pinch of fresh chives and parsley. Served with two slices of toasted bread to enjoy every drop of sauce.', 'بيني باستا باستا البيني المطبوخة ببراعة وممزوجة بصلصة إيطالية خاصة,مزيج غني من ثلاثة أنواع مختلفة من الصلصات لابتكار قاعدة بيضاء كريمية مع قطع طرية من صدر الدجاج. تعلوها جُبنة البارميزان المعتقة، الشيدر الأبيض، ورشة البقدونس الطازج. تُقدّم مع شريحتين من الخبز المحمص للاستمتاع بآخر قطرة من الصلصة.', 42.00, '/menu/0076-penne-pasta.webp', true, false, 380),
  (155, (select id from menu_categories where source_id = 4), '0155', 'Halloumi Sandwich', 'ساندويش الحلوم', 'Halloumi Sandwich Pan-seared golden halloumi layered in warm artisan brioche with signature za''atar, fresh homemade green pesto, smooth avocado guacamole, wild rocket, and sliced tomato, finished with extra virgin olive oil and sweet pomegranate molasses.', 'ساندويتش حلوم شرائح جبن الحلوم الذهبية المحمرة في خبز البريوش الحرفي الدافئ مع الزعتر الفاخر، بيستو الأعشاب الخضراء المحضر منزلياً، واكامولي الأفوكادو الناعم، جرجير بري، وشرائح الطماطم، تعلوها لمسة من زيت الزيتون البكر ودبس الرمان الحلو.', 35.00, '/menu/0155-halloumi-sandwich.webp', true, false, 390),
  (157, (select id from menu_categories where source_id = 4), '0157', 'Cheesy Roasted Beef Sandwich', 'ساندويش اللحم', 'Cheesy Roasted Beef Sandwich Tender roasted beef strips layered with rich homemade red pesto, melted mozzarella cheese, fresh tomato slices, and crisp greens, served warm in a toasted artisan bun.', 'ساندويش شرائح اللحم البقري بالجبن شرائح لحم بقر مشوي طرية مع صوص البيستو الأحمر المحضّر لدينا، جبن الموزاريلا المذاب، شرائح الطماطم الطازجة، والخضار الخضراء المنعشة، تُقدّم دافئة في خبز محمص فاخر.', 39.00, '/menu/0157-cheesy-roasted-beef-sandwich.webp', true, false, 400),
