  (214, (select id from menu_categories where source_id = 4), '0214', 'Creamy Egg with Chicken', 'بيض كريمي مع دجاج', 'Creamy Egg with Chicken Velvety soft-scrambled eggs paired with tender herb-marinated chicken, served over toasted artisan brioche and garnished with fresh chives.', 'بيض كريمي مع الدجاج بيض مخفوق ناعم ومخملي يُقدّم مع دجاج طري متبل بالأعشاب، فوق شريحة من خبز البريوش المحمص ومزين بالثوم المعمر الطازج.', 32.00, '/menu/0214-creamy-egg-with-chicken.webp', true, false, 440),
  (163, (select id from menu_categories where source_id = 5), '0163', 'Chicken Ceaser Salad', 'سلطة السيزر مع الدجاج', 'Chicken Caesar Salad Tender grilled chicken breast served over crisp romaine lettuce, tossed in rich Caesar dressing, topped with shaved Parmesan cheese and garlic butter croutons.', 'سلطة سيزر الدجاج شرائح صدور الدجاج المشوية الطرية على طبقة من خس الرومين الطازج، ممزوجة بصلصة السيزر الغنية، يعلوها جبن البارميزان المبشور ومكعبات الخبز المحمص بالثوم والزبدة.', 38.00, '/menu/0163-chicken-ceaser-salad.webp', true, false, 450),
  (201, (select id from menu_categories where source_id = 5), '0201', 'Rocca with Quinoa', 'الجرجير مع الكينوا', 'Rocca with Quinoa Salad Crisp rocket leaves and fluffy organic quinoa tossed with cherry tomatoes, fresh pomegranate seeds, toasted nuts, and crunchy baked corn pieces, served with tender grilled chicken breast . Finished with a signature blend of balsamic vinaigrette and zesty Italian dressing.', 'سلطة الروكا مع الكينوا أوراق الجرجير الطازجة مع الكينوا العضوية الهشة، مطعّمة بطماطم شيري، حبات الرمان الطازجة، المكسرات المحمصة، وقطع الذرة ، تُقدّم مع صدر الدجاج المشوي الطري. ممزوجة بلمسة خاصة من صلصة البلسميك والتتبيلة الإيطالية المنعشة.', 34.00, '/menu/0201-rocca-with-quinoa.webp', true, false, 460),
  (66, (select id from menu_categories where source_id = 6), '0066', 'Eggs Benedict', 'بيض البينيدكت', 'Eggs Benedict Crisp layered potato pavé topped with creamy mashed avocado, two perfectly poached eggs, and rich hollandaise sauce, finished with a pinch of sweet paprika, fresh rocca, and crumbled feta.', 'إيجز بينيديكت طبقات البطاطس المقرمشة يعلوها مهروس الأفوكادو الكريمي، بيضتان مسلوقتان بدقة، وصوص الهولنديز الغني، مع لمسة من البابريكا الحلوة، الجرجير الطازج، ورشة من جبن الفيتا.', 52.00, '/menu/0066-eggs-benedict.webp', true, true, 470),
  (67, (select id from menu_categories where source_id = 6), '0067', '3 Mini Sandwiches', 'ساندويتشات صغير 3', 'Falafel Donuts Crisp, donut-shaped artisanal falafel crafted from spiced chickpeas and fresh herbs, served over smooth tahini drizzle, garnished with pickled turnips, wild rocket, toasted sesame, and pomegranate seeds.', 'دونات الفلافل فلافل حرفية مقرمشة على شكل دونات محضرة من الحمص المتبل والأعشاب الطازجة، تُقدّم فوق صوص الطحينة الناعمة، وتُزيَّن باللفت المخلل، الجرجير البري، السمسم المحمص، وحبات الرمان.', 32.00, '/menu/0067-3-mini-sandwiches.webp', true, false, 480),
  (70, (select id from menu_categories where source_id = 6), '0070', 'Healthy Granola', 'جرانولا', 'Healthy Granola Bowl House-baked toasted oat granola blended with mixed nuts and seeds, served over silky Greek yogurt, topped with fresh seasonal berries, chia seeds, and a drizzle of pure honey.', 'جرانولا صحية جرانولا الشوفان المخبوزة منزلیاً والمحمصة مع مكسرات وبذور مشكلة، تُقدّم فوق زبادي يوناني حريري، وتُزيَّن بالتوت الفاكهي الطازج، بذور الشيا، ورذاذ من العسل الصافي.', 40.00, '/menu/0070-healthy-granola.webp', true, false, 490),
  (75, (select id from menu_categories where source_id = 6), '0075', 'Green Shakshooka', 'شكشوكة', '', '', 36.00, '/menu/0075-green-shakshooka.webp', false, false, 500),
  (175, (select id from menu_categories where source_id = 6), '0175', 'Shakshooka', 'شكشوكة', 'Shakshooka Two eggs gently cooked and nestled in a rich, slow-simmered sauce of vine-ripened tomatoes, a sweet bell pepper mixture, garlic, and aromatic Mediterranean spices. Served warm with artisan Arabic bread.', 'شكشوكة بيضتان مطهوتان ببراعة ورفق داخل صلصة غنية ومطهوة ببطء من الطماطم الناضجة، مزيج الفلفل الرومي الحلو، الثوم، والتوابل المتوسطية العطرية. تُقدّم دافئة مع الخبز العربي المخبوز على الطريقة الحرفية.', 36.00, '/menu/0175-shakshooka.webp', true, false, 510),
  (212, (select id from menu_categories where source_id = 6), '0212', 'Greek Omlette', 'اومليت يوناني', 'Greek Omelette Fluffy eggs folded with tangy Greek feta cheese, sweet cherry tomatoes, Kalamata olives, and fresh greens, finished with aromatic oregano and delicate herbs.', 'أومليت يوناني بيض هشش مطوي مع جبن الفيتا اليوناني الفاخر، الطماطم الكرزية الحلوة، زيتون الكالاماتا، والأوراق الخضراء الطازجة، يُكَمَّل بنكهة الزعتر البري والأعشاب العطرية.', 32.00, '/menu/0212-greek-omlette.webp', true, false, 520),
  (213, (select id from menu_categories where source_id = 6), '0213', 'French Omlette', 'ااومليت فرنسي', 'French Omelette Smooth, golden, and soft-folded eggs with a rich, velvety center, finished with a brush of fine butter and freshly chopped herbs.', 'أومليت فرنسي بيض مطوي بعناية بقوام ذهبي أملس ومركز كريمي طري، مطلي بلمسة من الزبدة الفاخرة ومزين بالأعشاب الطازجة.', 27.00, '/menu/0213-french-omlette.webp', true, false, 530)
on conflict (source_id) do update set
  category_id    = excluded.category_id,
  name_en        = excluded.name_en,
  name_ar        = excluded.name_ar,
  description_en = excluded.description_en,
  description_ar = excluded.description_ar,
  price          = excluded.price,
  image_path     = excluded.image_path,
  is_available   = excluded.is_available,
  is_signature   = excluded.is_signature,
  sort_order     = excluded.sort_order;

-- -------------------------------------------------------------- modifiers
--
-- The incumbent has none of this. Prices sourced from their own add-on products where
-- one exists; everything marked UNCONFIRMED is a proposal awaiting the owner's sign-off.

insert into menu_item_modifier_groups (id, name_en, name_ar, min_select, max_select, sort_order) values
  ('11111111-1111-4111-8111-000000000001', 'Milk',       'الحليب',      1, 1, 10),
  ('11111111-1111-4111-8111-000000000002', 'Size',       'الحجم',       1, 1, 20),
  ('11111111-1111-4111-8111-000000000003', 'Extras',     'إضافات',      0, 4, 30),
  ('11111111-1111-4111-8111-000000000004', 'Add to dish','إضافة للطبق', 0, 3, 40)
on conflict (id) do nothing;

insert into menu_item_modifier_options (group_id, name_en, name_ar, price_delta, is_default, sort_order) values
